\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 {\field{\*\fldinst HYPERLINK "hida://5240[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Ornamentale Initialen}}\plain \f1\lang1033\fs24  in Deckfarben und Gold (5\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 68\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ): 4\endash 5-zeilige Initialen mit blauem Stamm (Init.-H\u246 \'f6he: 2\endash 3 cm) mit Wei\u223 \'dflinienfiligran (konturbegleitende und gebogte Linien, Zickzacksteg, Perlen und Punkte [auch in Reihen]) vor goldenem vielfach gebuchteten Feld (5\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  mit stark ausgeweiteter Fl\u228 \'e4che und bunten Ranken mit Trifolien) oder golden umrahmtem rosafarbenen Feld mit Wei\u223 \'dflinienfiligran (konturbegleitende F\u228 \'e4den, H\u228 \'e4kchen, Punkte). Binnenraum: farbige Ranken mit Trifolien vor goldenem Grund. Farben\plain \f1\caps\lang1033\fs24 : \plain \f1\lang1033\fs24 Dunkelrosa, Hellrot, Blau, Wei\u223 \'df, Schwarz, Blattgold.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 {\field{\*\fldinst HYPERLINK "hida://5240[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Rankenbord\u252 \'fcren}}\plain \f1\lang1033\fs24  in Deckfarben und Gold (5\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 9\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 11\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 68\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ): einmal (5\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) flankieren den Schriftspiegel breite Farbleisten mit grauem (einst silbernem) und wei\u223 \'dfem Filigran (Wellenlinien, Zickzackb\u228 \'e4nder, Fadenranken, Perlen, H\u228 \'e4kchen) sowie goldenen Motiven (Pollen, Quadrate), ein anderes Mal (68\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) s\u228 \'e4umen ihn zwei schmale Parallelst\u228 \'e4be in Rosa und Gold; in allen F\u228 \'e4llen stehen frei auf dem Pergament Dornblattranken mit bewimperten Goldpollen und goldenen Lanzettbl\u228 \'e4ttern \endash  an exponierten Stellen um farbige Profilbl\u228 \'e4tter und Bl\u252 \'fcten (G\u228 \'e4nsebl\u252 \'fcmchen, Rosetten, Phantasiebl\u252 \'fcten) erweitert. Farben: Blau, Hellrot, Dunkelrosa, Gr\u252 \'fcn, Wei\u223 \'df, Schwarz, Silber, Blattgold. }

