\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 \plain \f1\lang1033\fs24 Kleine {\field{\*\fldinst HYPERLINK "hida://5240[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Randbord\u252 \'fcren}}\plain \f1\scaps\lang1033\fs24  \plain \f1\lang1033\fs24 (z.B. 3\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 4\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 15\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 15\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ,\plain \f1\super\lang1033\fs24  \plain \f1\lang1033\fs24 16\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 21\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 24\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 31\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ): links vertikal in H\u246 \'f6he des Schriftspiegels sich vielfach verzweigende Fadenranken mit Goldpollen, bewimperten goldenen Lanzettbl\u228 \'e4ttern, Dornbl\u228 \'e4ttern und diversen Bl\u252 \'fcten (3- und 4-bl\u228 \'e4ttrige Rosetten [teils mit spitzen Zwischenbl\u228 \'e4ttern], Kornblumen, Nelken, Phantasiebl\u252 \'fcten mit dick entwachsendem Kolben) und Fr\u252 \'fcchten (Erdbeeren, rote und gr\u252 \'fcne Samenkapseln). Farben: Rosa, Hellrot, Orange, Blau, Gr\u252 \'fcn, Wei\u223 \'df, Schwarz, Blattgold. }

