\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 I\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash V\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacant. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 6\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24 Kalendarium (mit Nachtr\u228 \'e4gen den 17. Jhs.). 7\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 8\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Stundengebete zum hl. Kreuz. 9\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 12\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Marienmesse. 12\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 13\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs24 Evangelienlesung nach Johannes. 13\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 14\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs24 Evangelienlesung nach Lukas. 14\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 15\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs24 Evangelienlesung nach Matth\u228 \'e4us. 15\plain \f1\super\lang1033\fs24 r\endash v \plain \f1\lang1033\fs24 Evangelienlesung nach Markus. 16\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 49\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Stundengebete zur Jungfrau Maria (27\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 36\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacant). 50\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 55\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  erneuerte Stundengebete zur Jungfrau Maria. 55\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacat. 56\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 62\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  sieben Bu\u223 \'dfpsalmen. 62\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 66\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24 Litaneien. 66\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 67\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Psalm 69. 67\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 69\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  verschiedene Gebete. 69\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacat. 70\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 91\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Totenoffizium. 91\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 92\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacant.}

