\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 8\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Kalender (ohne Januar, Juni, Juli, s.o.). 9\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 16\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Horae zum hl. Kreuz. 17\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  vacat. 17\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 23\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Horae zum hl. Geist. 23\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacat. 24\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 116\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Marienmesse (vacant: 42\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 43\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 61\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 62\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 74\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 79\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 80\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 85\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 90\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 95\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 117\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ). 117\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 139\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Sieben Bu\u223 \'dfpsalmen. 139\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 140\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  vacant. 140\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 184\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Horae zu den Toten. 185\plain \f1\super\lang1033\fs24 r\endash v \plain \f1\lang1033\fs24 Gebet zur Trinit\u228 \'e4t. 185\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 186\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Gebet zum hl. Michael. 186\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 187\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Gebet zum hl. Adrian. 187\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 188\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Gebet zum hl. Sebastian. 188\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 189\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Gebet zum hl. Antonius. 189\plain \f1\super\lang1033\fs24 r\endash v \plain \f1\lang1033\fs24 Gebet zum hl. Antonius. 190\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs24 Rest eines Heiligengebets. 190\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Gebet zum hl. Johannes dem T\u228 \'e4ufer. 191\plain \f1\super\lang1033\fs24 r\endash v \plain \f1\lang1033\fs24 Gebet zum hl. Christophorus. 191\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 191a\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Gebet zur hl. Katharina. 191a\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 192\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Gebet zur hl. Barbara. 192\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 193\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Gebet zur hl. Apollonia. 193\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24  Gebet zur hl. Maria Magdalena.  }

