\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 I\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 1a\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  vacant. 1a\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Miniatur. 1b\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 51\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Francesco Petrarca}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Le livre des triumphes}}\plain \f1\lang1033\fs24  (= I Trionfi in franz\u246 \'f6sischer Prosa-\u220 \'dcbersetzung von {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Georges de la Forge}}\plain \f1\lang1033\fs24 : 1b\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 4\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24 Pr\u228 \'e4ambel; 4\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 17\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Triumphus Cupidinis [8a\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24  vacant]. 17\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacat. 18\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 21\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Triumphus Pudicitiae; 22\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 33\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Triumphus Mortis; 33\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacat; 34\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 41\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Triumphus Famae; 42\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  nachgetragene [?] ganzseitige Zeichnung; 42\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacat; 43\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 47\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Triumphus Temporis; 47\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacat; 48\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 51\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Triumphus Aeternitatis). 52\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 54\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacant.}

