\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 \plain \f1\lang1033\fs24 Kleine {\field{\*\fldinst HYPERLINK "hida://5240[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Miniaturen}}\plain \f1\lang1033\fs24  (rechteckiges Format mit Halbfiguren, jeweils schwarz/golden gerahmt; Farben wie Randbord\u252 \'fcren, zus\u228 \'e4tzlich verschiedene Braunt\u246 \'f6ne, Grau, Inkarnat, Silber; Ma\u223 \'dfe: 3,5\endash 5 x 3,5\endash 4 cm): 3\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  schreibender {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Evangelist Lukas}}\plain \f1\lang1033\fs24 . 3\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  schreibender {\field{\*\fldinst HYPERLINK "hida://5500[1]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Evangelist Matth\u228 \'e4us}}\plain \f1\lang1033\fs24 . 4\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  schreibender {\field{\*\fldinst HYPERLINK "hida://5500[2]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Evangelist Markus}}\plain \f1\lang1033\fs24 . 5\plain \f1\super\lang1033\fs24 r\plain \f1\sub\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[3]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Mater dolorosa}}\plain \f1\lang1033\fs24  (betende Maria im Strahlenkranz, halb \u252 \'fcberschrieben von sehr viel sp\u228 \'e4terem Kommentar). 7\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[4]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Maria und der Schmerzensmann}}\plain \f1\lang1033\fs24 . 8\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  trauernde Maria mit dem Leichnam Jesu. 77\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[5]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Trinit\u228 \'e4t}}\plain \f1\lang1033\fs24  (Gottvater [Gesicht abgekratzt], der Gekreuzigte und die Taube des hl. Geistes); {\field{\*\fldinst HYPERLINK "hida://5500[6]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 hl. Michael}}\plain \f1\lang1033\fs24  mit Schwert. 77\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Johannes der T\u228 \'e4ufer; {\field{\*\fldinst HYPERLINK "hida://5500[7]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Johannes der Evangelist}}\plain \f1\lang1033\fs24 . 78\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[8]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 hll. Petrus und Paulus}}\plain \f2\lang1033\fs24 .\plain \f1\lang1033\fs24  78\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[9]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 hl. Andreas}}\plain \f1\lang1033\fs24 ; {\field{\*\fldinst HYPERLINK "hida://5500[10]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 hl. Stephan}}\plain \f1\lang1033\fs24 . 79\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[12]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 hl. Laurentius}}\plain \f1\lang1033\fs24 ; {\field{\*\fldinst HYPERLINK "hida://5500[13]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 hl. Sebastian}}\plain \f1\lang1033\fs24 . 79\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[14]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 hl. Nikolaus}}\plain \f1\lang1033\fs24 . 80\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[15]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 hl. Katharina}}\plain \f1\lang1033\fs24 . 80\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[16]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 hl. Margarete}}\plain \f1\lang1033\fs24  mit Drachen. 81\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[17]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 hl. Barbara}}\plain \f1\lang1033\fs24 .  }

