\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 {\field{\*\fldinst HYPERLINK "hida://5240[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Kalenderminiaturen}}\plain \f1\lang1033\fs24  (Farben wie\plain \f1\b\lang1033\fs24  \plain \f1\lang1033\fs24 Randleisten, zus\u228 \'e4tzlich Silber; Ma\u223 \'dfe: 4 x 3 cm) als Tierkreiszeichen und Monatsarbeiten im seitlichen Vertikalband (jeweils in rechteckiger Szene, die oben und unten von ornamental verzierten Feldern flankiert ist): 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 tafelnder vornehmer Herr}}\plain \f1\lang1033\fs24 , der bedient wird. 1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[1]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Wassermann}}\plain \f1\lang1033\fs24  (Januar). 2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[2]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 sich w\u228 \'e4rmende Personen am Kaminfeuer}}\plain \f1\lang1033\fs24 . 2\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[3]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fische}}\plain \f1\lang1033\fs24  (Februar). 3\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[4]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Mann beim Baumschneiden}}\plain \f1\lang1033\fs24 . 3\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[5]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Widder}}\plain \f1\lang1033\fs24  (M\u228 \'e4rz). 4\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[6]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 vornehmer J\u252 \'fcngling mit Blume}}\plain \f1\lang1033\fs24  in Landschaft. 4\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[7]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Stier}}\plain \f1\lang1033\fs24  (April). 5\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[8]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Liebespaar auf einem Pferd}}\plain \f1\lang1033\fs24  in Landschaft. 5\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[9]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Zwilling}}\plain \f1\lang1033\fs24  als Figur mit zwei (m\u228 \'e4nnlich + weiblich) Oberk\u246 \'f6rpern (Mai). 6\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[10]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 mit Sense arbeitender Bauer}}\plain \f1\lang1033\fs24 . 6\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[11]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Krebs}}\plain \f1\lang1033\fs24  (Juni). 7\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  zwei {\field{\*\fldinst HYPERLINK "hida://5500[12]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Bauern bei Getreidemahd}}\plain \f1\lang1033\fs24 . 7\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[13]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 L\u246 \'f6we}}\plain \f1\lang1033\fs24  (Juli). 8\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  zwei {\field{\*\fldinst HYPERLINK "hida://5500[14]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 dreschende Gesellen}}\plain \f1\lang1033\fs24 . 8\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[15]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Jungfrau}}\plain \f1\lang1033\fs24  (August). 9\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  zwei {\field{\*\fldinst HYPERLINK "hida://5500[16]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Knechte beim Keltern von Trauben}}\plain \f1\lang1033\fs24 . 9\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[17]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Waage}}\plain \f1\lang1033\fs24 , von Jungfrau gehalten (September). 10\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[18]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 S\u228 \'e4mann}}\plain \f1\lang1033\fs24 . 10\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[20]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Skorpion}}\plain \f1\lang1033\fs24  (Oktober). 11\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[21]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Tr\u252 \'fcffelsuche}}\plain \f1\lang1033\fs24 . 11\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Kentaur als {\field{\*\fldinst HYPERLINK "hida://5500[22]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Sch\u252 \'fctze}}\plain \f1\lang1033\fs24  (November). 12\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[23]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Mann und Frau beim Schlachten}}\plain \f1\lang1033\fs24 . 12\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[24]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Steinbock}}\plain \f1\lang1033\fs24  (Dezember).}

