\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Memorialverse. 1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  komputistisches Schema. 2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 7\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Kalender. 7a\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24  vacant. 8\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 14\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Evangelienperikopen. 15\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  vacat. 15\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 16\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Miniaturen. 16\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 19\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24 Mariengebet. 20\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  vacat. 20\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 21\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Miniaturen. 21\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 69\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  kleines Marienoffizium (darin 7 ganzseitige Miniaturen). 69\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacat. 70\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Miniatur. 70\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 73\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  kleines Kreuzoffizium. 74\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Miniatur. 74\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 77\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  kleines Heiliggeistoffizium. 77\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 79\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacant. 80\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Miniatur. 80\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 90\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  sieben Bu\u223 \'dfpsalmen. 90\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 96\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Allerheiligenlitanei. 96\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacat. 97\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Miniatur. 97\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 136\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  gro\u223 \'dfes Totenoffizium. 136\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 137\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  nachgetragene Gebete. 138\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 147\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Mariengebete. 147\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacat. 148\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Gebet. 148\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 149\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Miniaturen. 149\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 159\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Passion nach Johannes. 159\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 160\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Gebet zur hl. Veronika (mit Miniatur). 161\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 163\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Klage Mariens (mit Miniatur). 163\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 164\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Gebete. 164\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 166\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Ablassgebet. 166\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 197\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Gebete und F\u252 \'fcrbitten. 198\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 200\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacant. Siehe \plain \f1\scaps\lang1033\fs24 Remak-Honnef\plain \f1\lang1033\fs24 .}

