\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 I\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24  vacant. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 12\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Kalender (Hinweise auf Toul). 13\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 18\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Evangelien. 18\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 20\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacant. 21\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 67\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  kleines Marienoffizium (30\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 40\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 53\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacant; 57\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  fehlender Text des herausgenommenen Blattes deutlich sp\u228 \'e4ter eingef\u252 \'fcgt). 67\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacat. 68\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 83\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Sieben Bu\u223 \'dfpsalmen und Litanei. 83\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 85\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Orationen (franz\u246 \'f6sische Rubriken). 85\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacat. 86\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 88\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  kleines Kreuzoffizium. 89\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 91\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  kleines Heiliggeistoffizium. 91\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacat. 92\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 123\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Totenoffizium (Gebrauch von Rouen). 123\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacat. 124\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 130\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Mariengebete. 130\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 137\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Suffragien (franz\u246 \'f6sische Rubriken). 137\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 139\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  franz\u246 \'f6sisches Gebet. 139\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 140\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacant. Siehe \plain \f1\scaps\lang1033\fs24 Remak-Honnef\plain \f1\lang1033\fs24 .}

