\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5260[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Pergament}}\plain \f1\lang1033\fs24      {\field{\*\fldinst HYPERLINK "hida://5706[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 III + 435 Bl.}}\plain \f1\lang1033\fs24      {\field{\*\fldinst HYPERLINK "hida://5360[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 20 x 13,5 cm}}\plain \f1\lang1033\fs24      {\field{\*\fldinst HYPERLINK "hida://5130[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Paris}}\plain \f1\lang1033\fs24      (Jean Pichore und Werkstatt)     {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 um 1494\endash 1500}}}

