\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 \plain \f1\lang1033\fs24 Kleine {\field{\*\fldinst HYPERLINK "hida://5240[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Miniaturen}}\plain \f1\scaps\lang1033\fs24  \plain \f1\lang1033\fs24 (1-spaltig; Ma\u223 \'dfe: 4,5\endash 8 x 4,5 cm; Farben: verschiedene Nuancen von Blau und Gr\u252 \'fcn, Lila, Hell- und Dunkelrot, Rosa, Orange, Gelb, Braun, Grau, Wei\u223 \'df, Schwarz, Inkarnat, Pinselgold): rechteckige Szenen, umrahmt von schmaler goldener Leiste mit rotem Kontur. 85\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Gei\u223 \'dfelung Christi}}\plain \f1\lang1033\fs24 . 87\plain \f1\super\lang1033\fs24 v {\field{\*\fldinst HYPERLINK "hida://5500[1]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Kreuztragung}}\plain \f1\lang1033\fs24 . 89\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[2]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Kreuzigung}}\plain \f1\lang1033\fs24 . 105\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[3]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Grablegung}}\plain \f1\lang1033\fs24 . 108\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[4]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 hl. Veronika}}\plain \f1\lang1033\fs24  mit dem Schwei\u223 \'dftuch. 140\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Verk\u252 \'fcndigung an die Hirten. 141\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[5]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 hl. Stephan}}\plain \f1\lang1033\fs24 . 145\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  hl. {\field{\*\fldinst HYPERLINK "hida://5500[6]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Evangelist Johannes}}\plain \f1\lang1033\fs24 . 151\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[7]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 hl. Thomas}}\plain \f1\lang1033\fs24 . 169\plain \f1\super\lang1033\fs24 r {\field{\*\fldinst HYPERLINK "hida://5500[8]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Anbetung der Hll. Drei K\u246 \'f6nige}}\plain \f1\lang1033\fs24 . 243\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  auferstandener Christus erscheint den Aposteln. 325\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  zwei Engel halten den {\field{\*\fldinst HYPERLINK "hida://5500[9]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Kelch mit der Hostie}}\plain \f1\lang1033\fs24 . 428\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[10]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Auferweckung des Lazarus}}\plain \f1\lang1033\fs24 . }

