\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 [Zahlreiche schlichte ornamentale Initialen sowie goldene Paragraphzeichen vor Deckfarben in den Nachtr\u228 \'e4gen in Antiqua (s.o.), Frankreich, um 1600 (z.B. 153\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 153\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 158\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 159\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 205\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ); zus\u228 \'e4tzlich 21 eingeklebte Fragmente aus Marcoussis in drei verschiedenen Stilgruppen, 15./16. Jh.; siehe Fragmente aus Marcoussis, Kat. 70.]}

