\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt \plain \f1\lang1033\fs24 (\u252 \'fcberwiegend fl\u228 \'e4misch): I\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash II\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacant. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 18\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Tagzeiten von Jesus Christus (5\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacat). 19\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 38\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  sieben Bu\u223 \'dfpsalmen und Litanei. 38\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacat. 39\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 60\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Totenwache (lateinisch). 61\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 99\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Gedichte}}\plain \f1\lang1033\fs24  (61\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24  an hl. Maria; 62\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24  an Gott; 63\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24  an Evangelisten Johannes; 64\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  an die Schutzengel; 64\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacat; 65\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24  an Evangelisten Matth\u228 \'e4us; 66\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24  an Evangelisten Lukas; 67\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  an hl. Petrus; 67\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 68\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  an hl. Andreas; 69\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 70\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  an hl. Maurus; 70\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 71\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  an hl. Jakob; 72\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24  an hl. Mauritius; 73\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 74\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  an hl. Jodokus; 74\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 75\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  an hl. Arnold; 76\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  an hl. Donatus; 76\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 77\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  an hl. Augustinus; 78\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 79\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  an hl. Franziskus; 79\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 80\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  an das hl. Sakrament des Altars; 80\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  lateinische Verse; 81\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 82\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  an hl. Vinzenz; 82\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 83\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  an hl. Sebastian; 84\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 85\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  an hl. Makarius; 85\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 86\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  an hl. Christophorus; 87\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24  an einen M\u228 \'e4rtyrer; 88\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24  an hl. Leonhard; 89\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24  an hl. Fiakrius; 90\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24  an hl. Martin; 91\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24  an hl. Livinus (kopfst\u228 \'e4ndig eingebunden); 92\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24  an hl. Johannes den T\u228 \'e4ufer; 93\plain \f1\super\lang1033\fs24 r\endash v \plain \f1\lang1033\fs24 an Jungfrau Maria; 94\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24  an hl. Magdalena; 95\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24  an hl. Barbara; 96\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 99\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  an Gott). 100\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  f\u252 \'fcnf Gr\u252 \'fc\u223 \'dfe an den Herrn. 100\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 101\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Passion des Herrn. 101\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 108\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Gebete in Prosa. 108\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 110\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Lied an Maria. 110\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 118\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Lied an Gott. 118\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 125\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  die 15 Freuden der Jungfrau Maria. 126\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 130\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Gedichte an Maria. 130\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 134\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Gebet. 134\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 135\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  acht Mariengr\u252 \'fc\u223 \'dfe. 136\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 140\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Gebete in Prosa. 140\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 142\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Gedicht an Maria. 142\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacat. 143\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 155\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Passion Christi (nach Evangelien), Ende fehlt. Siehe \plain \f1\scaps\lang1033\fs24 Petzet\plain \f1\lang1033\fs24 .}

