\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 {\field{\*\fldinst HYPERLINK "hida://5240[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Zeilenf\u252 \'fcllornamentik}}\plain \f1\scaps\lang1033\fs24  \plain \f1\lang1033\fs24 (z.B. 10\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 13\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 15\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 16\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 29\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 29\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 30\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 77\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 103\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ; Farben wie Goldinitialen): schmale horizontale Leisten in Rosa und Blau mit Wei\u223 \'dflinienfiligran (Wellen- und Zickzacklinien, H\u228 \'e4kchen, B\u246 \'f6gen, Voluten, Fadenranken, Punkte), voneinander getrennt durch kleine goldene Elemente (Pfeilbl\u228 \'e4tter, Perlen, Dreiecke, Rauten), umrandet von schwarzem Kontur.  }

