1\b\lang1033\fs24  \plain \f1\lang1033\fs24 29\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 30\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24 Psalm 66. 30\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 33\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs24 verschiedene Gebete. 33\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 35\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24 Psalm 90. 35\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 36\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24 Gebet (\plain \f1\i\lang1033\fs24 Benedicat me imperialis maiestas\plain \f1\lang1033\fs24 )\plain \f1\i\lang1033\fs24 .\plain \f1\lang1033\fs24  36\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 37\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24 Gebet (\plain \f1\i\lang1033\fs24 Crux Christi sit semper mecum\plain \f1\lang1033\fs24 ). 37\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 41\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24 Gebet (\plain \f1\i\lang1033\fs24 O Excellentissima\plain \f1\lang1033\fs24 ). 41\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 43\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs24 Gebet (\plain \f1\i\lang1033\fs24 O gloriosa Domina, quae filium Dei portasti\plain \f1\lang1033\fs24 )\plain \f1\i\lang1033\fs24 .\plain \f1\b\lang1033\fs24  \plain \f1\lang1033\fs24 43\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 45\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24 Gebet (\plain \f1\i\lang1033\fs24 Sancta Maria, mater Domini nostri Ihesu Christi dulcissima\plain \f1\lang1033\fs24 )\plain \f1\i\lang1033\fs24 .\plain \f1\lang1033\fs24  45\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 46\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24 Gebet (\plain \f1\i\lang1033\fs24 Fluat stilla de mamilla\plain \f1\lang1033\fs24 ). 46\plain \f1\su