vor Kaiphas}}\plain \f1\lang1033\fs24 . 89\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[15]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Gei\u223 \'dfelung Christi}}\plain \f1\lang1033\fs24 . 91\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[16]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Kreuztragung}}\plain \f1\lang1033\fs24 . 94\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[17]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Kreuzigung}}\plain \f1\lang1033\fs24  mit den Sch\u228 \'e4chern sowie den Trauernden und Beobachtern. 100\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[18]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Kreuzabnahme}}\plain \f1\lang1033\fs24 . 108\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[19]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Grablegung Christi}}\plain \f1\lang1033\fs24 . 111\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[20]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 den drei Marien erscheint am leeren Grab der Engel}}\plain \f1\lang1033\fs24 . 116\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[21]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Himmelfahrt Christi}}\plain \f1\lang1033\fs24 . 121\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[22]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 J\u252 \'fcngstes Gericht}}\plain \f1\lang1033\fs24 . 127\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  betender K\u246 \'f6nig {\field{\*\fldinst HYPERLINK "hida://5500[23]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 David}}\plain \f1\lang1033\fs24 . 133\plain \f1\super\lang1033\fs24