\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 I\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash II\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacant. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 137\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Biblia}}\plain \f1\lang1033\fs24  sacra, Neues Testament (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Prologus; 2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 19\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Matth\u228 \'e4usevangelium; 19\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 20\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Prologus; 20\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 30\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Markusevangelium; 30\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 31\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Prologus; 31\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 50\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Lukasevangelium; 50\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Prologus; 50\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 64\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Johannesevangelium; 64\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 65\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Prologus zu Paulusbriefen; 65\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 72\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  R\u246 \'f6merbrief; 72\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 79\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  1. Korintherbrief; 79\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 83\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  2. Korintherbrief; 83\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 86\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Galaterbrief; 86\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 88\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Epheserbrief; 88\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 89\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Philipperbrief; 90\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 91\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Kolosserbrief; 91\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 92\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  1. Thessalonikerbrief; 92\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 93\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  2. Thessalonikerbrief; 93\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 95\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  1. Timotheusbrief; 95\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 96\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  2. Timotheusbrief; 96\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 97\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Titusbrief; 97\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 98\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Philemonbrief; 98\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 103\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Hebr\u228 \'e4erbrief; 103\plain \f1\super\lang1033\fs24 r\endash v \plain \f1\lang1033\fs24 Prologus; 103\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 120\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Apostelgeschichte; 120\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 121\plain \f1\super\lang1033\fs24 r\plain \f1\sub\lang1033\fs24  \plain \f1\lang1033\fs24 Prologus; 121\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 122\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Jacobusbrief; 122\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 124\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  1. Petrusbiref; 124\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 125\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  2. Petrusbrief; 125\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 127\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  1. Johannesbrief; 127\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  2. Johannesbrief; 127\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 128\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  3. Johannesbrief; 128\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 128\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Judasbrief; 128\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Prologus; 128\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 137\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Apokalypse). 137\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Kolophon (s.o.). 137\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 139\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacant.}

