\uc1
\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 {\field{\*\fldinst HYPERLINK "hida://5240[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Miniaturen und Randbord\u252 \'fcren}}\plain \f1\lang1033\fs24  (Farben wie Goldinitialen und Randbord\u252 \'fcren, zus\u228 \'e4tzlich  Braun, Ocker, Inkarnat; Ma\u223 \'dfe: 8,5 x 6\endash 6,5 cm): 17\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Kreuzigung mit Maria und Johannes}}\plain \f1\lang1033\fs24  in gr\u252 \'fcner Landschaft vor goldenem Grund. 45\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[1]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Mondsichelmadonna}}\plain \f1\lang1033\fs24 , umgeben von goldenen Strahlen vor blauem Grund mit wei\u223 \'dfen Wellenlinien und goldenen Punkten. 88\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[2]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Pfingstdarstellung}}\plain \f1\lang1033\fs24 ; Maria und die J\u252 \'fcnger in einem angedeuteten Innenraum mit gepflastertem Boden, dar\u252 \'fcber schwebt die Taube des hl. Geistes vor goldenem Grund. \endash  Jede der Miniaturen ist von Randbord\u252 \'fcren (wie bei Goldinitialen, s.o.) umgeben.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

