\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 I\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Marmorpapier (s.o.). I\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  kurze sp\u228 \'e4tere Notizen. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  vacat. 1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Miniatur. 2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 22\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  sieben Bu\u223 \'dfpsalmen mit Allerheiligenlitanei. 22\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 23\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Gebet}}\plain \f1\lang1033\fs24  zu Bu\u223 \'dfpsalmen (von {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Augustinus}}\plain \f1\lang1033\fs24 ). 24\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  vacat. 24\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Miniatur. 25\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 41\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Tagzeitengebete zum Leiden Christi. 41\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 43\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Passionsgebete. 43\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 46\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Gebet zu Christus. 46\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 47\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Gebet zu Gottvater. 47\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24  Mariengebet. 48\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 57\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Kommuniongebet. 58\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 65\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Passionsgebete. 65\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 66\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24 Hymnen zum Angesicht Christi. 67\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 82\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Mariengebete. 82\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 88\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \u8222 \'84Unseres Herren Klage\ldblquote . 88\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 108\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24 verschiedene Gebete. 109\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 110\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Heiligensuffragien. 111\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 118\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  verschiedene Gebete. 118\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 122\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Heiligengebete in Reimform. 122\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacat. 123\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 130\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24 Rosenkranz zur hl. Anna. 131\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 142\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Kalender (Fest \plain \f1\i\lang1033\fs24 den name Jhesus\plain \f1\lang1033\fs24  [15. Januar] wurde erst 1530 eingef\u252 \'fchrt). 143\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  vacat. 143\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Marmorpapier (s.o.). Siehe \plain \f1\scaps\lang1033\fs24 Schneider\plain \f1\lang1033\fs24 . }

