\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 {\field{\*\fldinst HYPERLINK "hida://5240[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Farbig hinterlegte ornamentale Randbord\u252 \'fcren in Deckfarben und Gold}}\plain \f1\lang1033\fs24  (z.B. 8\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 10\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 14\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 83\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 99\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 194\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 217\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ): in breit profiliertem Rahmen \endash  meist umseitig den Schriftspiegel umschlie\u223 \'dfend, aber auch als vertikale Leiste am \u228 \'e4u\u223 \'dferen Blattrand \endash  steht eine kreative Vielfalt an Ranken und Blumen (Rosen, Rosetten, Kornblumen, Disteln, G\u228 \'e4nsebl\u252 \'fcmchen, Stiefm\u252 \'fctterchen, Enzian, Nelken, Akelei, Lilien, Ringelblumen, Kelchbl\u252 \'fcten etc.), Fr\u252 \'fcchten (Erdbeeren, rote Beeren etc.), phantasievollen bunten V\u246 \'f6geln (flatternd, stehend, pickend etc.) sowie Pfauen (z.B. 52\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ), Insekten (Schmetterlinge, Fliegen, Libellen, Wespen etc.), Schnecken (z.B. 10\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 19\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ), \u196 \'c4ffchen (z.B. 70\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  zwei \u196 \'c4ffchen mit Wickelkind), vereinzelt auch Figuren (z.B. 69\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Tanzb\u228 \'e4r, am Seil gef\u252 \'fchrt von dunkelh\u228 \'e4utigem B\u228 \'e4renhalter) oder anderen Motiven (z.B: 190\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Goldgrund mit Granatapfelmuster) vor goldenem oder einfarbigem Feld. Farben: vielf\u228 \'e4ltige Nuancen von Blau, Rot, Gr\u252 \'fcn, Braun, Grau, Wei\u223 \'df, au\u223 \'dferdem Lila, Rosa, Orange, Gelb, Inkarnat, Schwarz, Pinselgold. }

