\uc1
\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 {\field{\*\fldinst HYPERLINK "hida://5240[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Weitere szenische Randbord\u252 \'fcren in Deckfarben und Gold}}\plain \f1\lang1033\fs24  (7\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 16\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 94\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 104\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 119\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 128\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 149\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ): \u228 \'e4hnlich den Randbord\u252 \'fcren mit Monatsarbeiten handelt es sich dort um {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Jagdszenen}}\plain \f1\lang1033\fs24  (94\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 104\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ), Drolerien (128\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Mann hindert L\u246 \'f6wen daran, einen Bienenkorb zu pl\u252 \'fcndern, sowie fliehende Schafherde) oder um Szenen, die auf zentrale Miniatur bezogen sind (z.B. 7\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[1]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Kreuztragung}}\plain \f1\lang1033\fs24  [neben {\field{\*\fldinst HYPERLINK "hida://5500[2]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Salvator mundi}}\plain \f1\lang1033\fs24 ]; 16\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  n\u228 \'e4chtliche {\field{\*\fldinst HYPERLINK "hida://5500[5]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Soldatenscharen}}\plain \f1\lang1033\fs24  [neben {\field{\*\fldinst HYPERLINK "hida://5500[4]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Jesus in Gethsemane}}\plain \f1\lang1033\fs24 ]; 149\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5500[7]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Trauerzug}}\plain \f1\lang1033\fs24  aus Kirche [neben {\field{\*\fldinst HYPERLINK "hida://5500[6]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Auferweckung des Lazarus}}\plain \f1\lang1033\fs24 ]). Farben wie Randbord\u252 \'fcren mit Zodiakalzeichen.}

