\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 {\field{\*\fldinst HYPERLINK "hida://5240[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Zweifarbige Fleuronn\u233 \'e9e-Initialen}}\plain \f1\lang1033\fs24  (24\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 35\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 48\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 53\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ): 3\endash 6-zeilige Initialen mit blauem Stamm (Init.-H\u246 \'f6he: 1,5\endash 3 cm) und rotem Fleuronn\u233 \'e9e. Besatz und Binnenraum: wie bei mehrfarbigen Fleuronn\u233 \'e9e-Initialen, doch stark reduziert.}

