\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 12\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24 Kalendarium. 13\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 18\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Tagzeiten zum hl. Kreuz. 18\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 19\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  vacant. 19\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Miniatur. 20\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 24\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Tagzeiten zum hl. Geist. 25\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 27\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs24 Beginn des Johannesevangeliums. 27\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 29\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24 aus dem Lukasevangelium. 29\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 31\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24 aus dem Matth\u228 \'e4usevangelium. 31\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 33\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs24 aus dem Markusevangelium. 33\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 35\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  sieben Verse des hl. Bernhard. 35\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 38\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Gebete und Hymnen zu Gott, der Jungfrau Maria und der Trinit\u228 \'e4t. 38\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 42\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Beda Venerabilis}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Oratio de septem ultimis verbis Iesu Christi}}\plain \f1\lang1033\fs24 . 42\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 45\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  verschiedene Heiligenf\u252 \'fcrbitten. 46\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  vacat. 46\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Miniatur. 47\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 55\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Messe zur Verehrung Mariens.\plain \f1\b\lang1033\fs24  \plain \f1\lang1033\fs24 55\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacat. 56\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 62\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Gebet zur Jungfrau Maria. 62\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 63\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs24 vacant. 63\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Miniatur. 64\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 145\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Tagzeiten zur Jungfrau Maria (nach r\u246 \'f6mischem Gebrauch). 146\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 147\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Hymnus zur hl. Maria Magdalena. 148\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  vacat. 148\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Miniatur. 149\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 166\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs24 sieben Bu\u223 \'dfpsalmen. 166\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 172\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Litaneien. 172\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 173\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs24 vacant. 173\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Miniatur. 174\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 213\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs24 Totenoffizium. 213\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24 vacat. }

