\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 I\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  vacat. 1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 13\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Kalendarium.\plain \f1\b\lang1033\fs24  \plain \f1\lang1033\fs24 13\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 14\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  vacant.\plain \f1\b\lang1033\fs24  \plain \f1\lang1033\fs24 14\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Miniatur. 15\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 16\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Gebet zur hl. Veronika. 16\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24  Gebet.\plain \f1\scaps\lang1033\fs24  \plain \f1\lang1033\fs24 17\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  vacat. 17\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Miniatur.\plain \f1\b\lang1033\fs24  \plain \f1\lang1033\fs24 18\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 22\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Stundengebete zum hl. Kreuz.\plain \f1\b\lang1033\fs24  \plain \f1\lang1033\fs24 23\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  vacat. 23\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Miniatur.\plain \f1\b\lang1033\fs24  \plain \f1\lang1033\fs24 24\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 28\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Stundengebete zum hl. Geist.\plain \f1\b\scaps\lang1033\fs24  \plain \f1\lang1033\fs24 29\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  vacat.\plain \f1\b\lang1033\fs24  \plain \f1\lang1033\fs24 29\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Miniatur.\plain \f1\b\lang1033\fs24  \plain \f1\lang1033\fs24 30\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 39\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Messe zur Jungfrau Maria.\plain \f1\b\lang1033\fs24  \plain \f1\lang1033\fs24 39\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 40\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  vacant.\plain \f1\b\scaps\lang1033\fs24  \plain \f1\lang1033\fs24 40\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Miniatur.\plain \f1\b\lang1033\fs24  \plain \f1\lang1033\fs24 41\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 129\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Stundengebete zur Jungfrau Maria nach r\u246 \'f6mischem Gebrauch (65\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 81\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 88\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 95\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 101\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 102\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 109\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 120\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 121\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  vacant; 65\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 81\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 88\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 95\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 102\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 109\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 121\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Miniaturen).\plain \f1\scaps\lang1033\fs24  \plain \f1\lang1033\fs24 129\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacat.\plain \f1\b\lang1033\fs24  \plain \f1\lang1033\fs24 130\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 141\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Marienmesse im Advent.\plain \f1\b\lang1033\fs24  \plain \f1\lang1033\fs24 141\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 142\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  vacant. \plain \f1\scaps\lang1033\fs24 1\plain \f1\lang1033\fs24 42\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Miniatur. 143\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 158\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  sieben Bu\u223 \'dfpsalmen.\plain \f1\b\lang1033\fs24  \plain \f1\lang1033\fs24 158\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 164\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Litaneien.\plain \f1\b\lang1033\fs24  \plain \f1\lang1033\fs24 164\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 165\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Psalm 69.\plain \f1\b\lang1033\fs24  \plain \f1\lang1033\fs24 165\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 170\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  verschiedene Gebete.\plain \f1\b\lang1033\fs24  \plain \f1\lang1033\fs24 171\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  vacat. 171\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Miniatur.\plain \f1\b\lang1033\fs24  \plain \f1\lang1033\fs24 172\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 220\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Totenmesse. 220\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vacat. 221\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 229\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Gebete zur Jungfrau Maria. 229\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 234\plain \f1\super\lang1033\fs24 r\plain \f1\b\lang1033\fs24  \plain \f1\lang1033\fs24 Athanasisches Glaubensbekenntnis.\plain \f1\b\lang1033\fs24  \plain \f1\lang1033\fs24 234\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \end